import fs from "node:fs/promises";
const core = await fs.readFile("shared/page-assistance.js", "utf8");
const dock = await fs.readFile("browser-extension/companion.js", "utf8");
const launcher = await fs.readFile("widget/launcher.js", "utf8");
await fs.mkdir("public", { recursive: true });
await fs.writeFile(
  "browser-extension/page-assistance.js",
  "// Generated by scripts/build-assistance.mjs. Do not edit.\n" + core,
);
await fs.writeFile(
  "public/webguide-widget.js",
  "// Generated by scripts/build-assistance.mjs. Do not edit.\n" +
    core +
    "\nwindow.WebGuideOpenCompanion = function(){\n" +
    dock +
    "\n};\n" +
    launcher,
);
console.log("Built shared core for extension and embedded widget");
